// Serialises every read-modify-write so concurrent events cannot drop entries.
let chain: Promise<unknown> = Promise.resolve();

function mutate<T>(fn: () => Promise<T>): Promise<T> {
  const next = chain.then(fn, fn);
  chain = next.catch(() => {});
  return next;
}

export function resolveCleanupTarget(hostname: string, ctx: TargetContext): CleanupTarget | null {
  const entry = matchesWatchlist(hostname, ctx.watchlist);
  if (ctx.mode !== 'protect') return entry ? entryTarget(entry) : null;

  if (isPlainHost(hostname)) return null;
  if (findProtectedSite(hostname, ctx.protectedSites)) return null;
  if (entry) return entryTarget(entry);

  const domain = normalizeDomain(hostname);
  return { kind: 'site', key: `site:${domain}`, domain, entry: null };
}

